# EVOLVE-BLOCK-START
import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def _edge_cost(G, s, t):
    """Edge cost with None treated as prohibitive."""
    c = G[s][t].get("cost")
    return c if c is not None else 1e9


def _path_cost(G, path):
    return sum(_edge_cost(G, path[i], path[i + 1]) for i in range(len(path) - 1))


def search_algorithm(src, dsts, G, num_partitions):
    """Broadcast routing via k-shortest-path candidates + simulated annealing.

    1. For each destination, generate up to K alternative low-cost simple
       paths (nx.shortest_simple_paths on a cost-weighted view), exposing
       parallel routes across networks.
    2. Initialize each (dst, partition) on its cheapest candidate route.
    3. Run simulated annealing over the joint assignment: each move swaps one
       (dst, partition) to another candidate route; the objective is total
       path cost plus a congestion penalty that grows when many partitions
       share an edge (approximating throughput saturation penalties in the
       evaluator). Moves are accepted per the Metropolis criterion with a
       geometric cooling schedule and a fixed random seed for determinism.
    """
    import random
    rng = random.Random(1234)

    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))

    # Cost-weighted view so None costs are avoided rather than crashing.
    hw = nx.DiGraph()
    for u, v, d in h.edges(data=True):
        c = d.get("cost")
        hw.add_edge(u, v, cost=c if c is not None else 1e9)

    K = 8
    routes = {}  # dst -> list of (path, base_cost)
    for dst in dsts:
        cands = []
        try:
            gen = nx.shortest_simple_paths(hw, src, dst, weight="cost")
            for path in gen:
                cands.append((path, _path_cost(hw, path)))
                if len(cands) >= K:
                    break
        except Exception:
            pass
        if not cands:
            p = nx.dijkstra_path(hw, src, dst, weight="cost")
            cands = [(p, _path_cost(hw, p))]
        # dedupe by edge set
        seen, uniq = set(), []
        for p, c in sorted(cands, key=lambda x: x[1]):
            key = tuple(zip(p, p[1:]))
            if key not in seen:
                seen.add(key)
                uniq.append((p, c))
        routes[dst] = uniq[:K]

    bc_topology = BroadCastTopology(src, dsts, num_partitions)
    P = bc_topology.num_partitions

    # Edge lists per (dst, route_idx) precomputed for fast objective eval.
    edge_lists = {
        dst: [[(p[i], p[i + 1]) for i in range(len(p) - 1)] for p, _ in rs]
        for dst, rs in routes.items()
    }
    base_costs = {dst: [c for _, c in rs] for dst, rs in routes.items()}
    n_routes = {dst: len(rs) for dst, rs in routes.items()}

    # assignment[(dst, part)] = route index; start at cheapest route.
    assignment = {(dst, p): 0 for dst in dsts for p in range(P)}
    edge_count = {}

    def route_edges(dst, r):
        return edge_lists[dst][r]

    # Build initial edge usage
    for (dst, p), r in assignment.items():
        for e in route_edges(dst, r):
            edge_count[e] = edge_count.get(e, 0) + 1

    LAMBDA = 0.05  # congestion penalty weight per extra flow on an edge

    def objective():
        """Total base cost + quadratic-ish congestion penalty on shared edges."""
        total = sum(base_costs[dst][r] for (dst, _), r in assignment.items())
        pen = 0.0
        for e, cnt in edge_count.items():
            if cnt > 1:
                pen += LAMBDA * base_cost_of_edge.get(e, 0.0) * cnt * (cnt - 1) / 2
        return total + pen

    # Per-edge base cost lookup for penalties
    base_cost_of_edge = {}
    for dst in dsts:
        for r, (path, c) in enumerate(routes[dst]):
            for e in edge_lists[dst][r]:
                if e not in base_cost_of_edge:
                    cc = hw[e[0]][e[1]]["cost"]
                    base_cost_of_edge[e] = cc if cc < 1e8 else 0.0

    def delta_swap(dst, part, new_r):
        """Delta objective from moving (dst, part) from cur_r to new_r."""
        cur_r = assignment[(dst, part)]
        old_edges = edge_lists[dst][cur_r]
        new_edges = edge_lists[dst][new_r]
        d = base_costs[dst][new_r] - base_costs[dst][cur_r]
        # remove old edges then add new edges; penalty delta computed directly
        def pen_pair(cnt):
            return cnt * (cnt - 1) / 2
        local = {}
        for e in old_edges:
            local[e] = local.get(e, 0) - 1
        for e in new_edges:
            local[e] = local.get(e, 0) + 1
        for e, dc in local.items():
            c0 = edge_count.get(e, 0)
            w = LAMBDA * base_cost_of_edge.get(e, 0.0)
            d += w * (pen_pair(c0 + dc) - pen_pair(c0))
        return d

    def apply_swap(dst, part, new_r):
        cur_r = assignment[(dst, part)]
        for e in edge_lists[dst][cur_r]:
            edge_count[e] -= 1
            if edge_count[e] == 0:
                del edge_count[e]
        for e in edge_lists[dst][new_r]:
            edge_count[e] = edge_count.get(e, 0) + 1
        assignment[(dst, part)] = new_r

    # Simulated annealing
    keys = list(assignment.keys())
    T0, T_END, ITER, COOL = 1.0, 1e-3, 3000, 0.998
    T = T0
    best_obj = objective()
    best_assign = dict(assignment)
    for it in range(ITER):
        dst, part = keys[rng.randrange(len(keys))]
        if n_routes[dst] < 2:
            continue
        new_r = rng.randrange(n_routes[dst])
        if new_r == assignment[(dst, part)]:
            continue
        d = delta_swap(dst, part, new_r)
        if d <= 0 or rng.random() < pow(2.718281828, -d / max(T, 1e-9)):
            apply_swap(dst, part, new_r)
            obj = best_obj + d
            if obj < best_obj:
                best_obj = obj
                best_assign = dict(assignment)
        T = max(T_END, T * COOL)

    # Restore best assignment and emit topology
    for (dst, part), r in best_assign.items():
        path, _ = routes[dst][r]
        edges = [[path[i], path[i + 1], G[path[i]][path[i + 1]]]
                 for i in range(len(path) - 1)]
        bc_topology.set_dst_partition_paths(dst, part, edges)

    return bc_topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
    # Use relative path from this file's location
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(row["src_region"], row["dst_region"], cost=None, throughput=num_vms * row["throughput_sent"] / 1e9)

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    # some pairs not in the cost grid
    no_cost_pairs = []
    for edge in G.edges.data():
        src, dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((src, dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


